Object.assign(TRANSLATIONS.en, {
  'pos.qtyWillAdd': 'Will add × {quantity}',
  'pos.qtyInvalid': 'Enter a whole quantity from 1 to 9,999',
  'pos.qtyMaximum': 'Maximum quantity is {max}',
  'pos.qtyAccumulationMaximum': 'An item quantity cannot exceed {max}',
});

function applyTranslations(lang) {
  const dict = TRANSLATIONS[lang] || TRANSLATIONS.ar;
  document.documentElement.setAttribute('data-lang', lang);
  // إعلام الشاشات التي تبني نصوصاً ديناميكية (مثل حالة الكمية) لتعيد بناءها باللغة الجديدة
  try { document.dispatchEvent(new CustomEvent('nexora:langchange', { detail: lang })); } catch (_) { /* تجاهل */ }
  document.documentElement.setAttribute('lang', lang);
  document.documentElement.setAttribute('dir', RTL_LANGS.includes(lang) ? 'rtl' : 'ltr');

  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const key = el.getAttribute('data-i18n');
    if (!dict[key]) return;
    // لا تستخدم textContent على العنصر كاملاً — يمسح الأيقونات (.nav-ico) وأي أبناء
    const ico = el.querySelector(':scope > .nav-ico');
    if (ico || el.querySelector(':scope > .nav-label')) {
      let label = el.querySelector(':scope > .nav-label');
      if (!label) {
        label = document.createElement('span');
        label.className = 'nav-label';
        // انقل النص الحالي (إن وُجد خارج الأيقونة) ثم حدّث الترجمة
        el.appendChild(label);
      }
      label.textContent = dict[key];
      // احذف أي عقد نصية مباشرة تحت الرابط (بقايا textContent السابق)
      Array.from(el.childNodes).forEach((n) => {
        if (n.nodeType === 3) n.remove();
      });
    } else {
      el.textContent = dict[key];
    }
  });
  // أعد الأيقونات بعد الترجمة إن وُجدت الدالة (common.js)
  if (typeof window.applyNavIcons === 'function') {
    try { window.applyNavIcons(); } catch (_) {}
  }
  document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (dict[key]) el.setAttribute('placeholder', dict[key]);
  });

  const switcher = document.getElementById('langSwitcher');
  if (switcher) switcher.value = lang;
  applyStaticTranslations(lang);
}

// تغطية الشاشات التي سبقت نظام data-i18n (منتجات، مخزون، تقارير، ورديات…)
// نحفظ النص العربي الأصلي في DOM مرة واحدة، لذلك يبقى تبديل اللغة قابلاً للعكس.
